<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_student();$uid=(int)current_user()['user_id'];$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM transactions WHERE transaction_id=? AND user_id=? AND status="active" LIMIT 1');$s->execute([$id,$uid]);$r=$s->fetch();if(!$r){flash('error','Transaction not found.');redirect('student/transactions.php');}$cats=user_categories($uid,$r['type']);$pageTitle='Edit Transaction';$activePage='transactions';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">EDIT</span><h1>Update transaction</h1><p>Your change is retained in the revision history.</p></div></section><section class="panel form-panel"><form class="form" method="post" action="<?=e(url('student/actions/transaction-update.php'))?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="transaction_id" value="<?=$id?>"><div class="form-grid two"><label>Type<select class="input" name="type"><option value="expense" <?=$r['type']==='expense'?'selected':''?>>Expense</option><option value="income" <?=$r['type']==='income'?'selected':''?>>Income</option></select></label><label>Date<input class="input" type="date" name="transaction_date" value="<?=e($r['transaction_date'])?>" required></label></div><label>Amount<input class="input" type="number" min="0.01" step="0.01" name="amount" value="<?=e((string)$r['amount'])?>" required></label><label>Description<input class="input" name="description" maxlength="255" value="<?=e($r['description'])?>"></label><label>Category<select class="input" name="category_id"><?php foreach($cats as$c):?><option value="<?=$c['category_id']?>" <?=$r['category_id']==$c['category_id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><div class="form-actions"><a class="btn btn-ghost" href="<?=e(url('student/transactions.php'))?>">Cancel</a><button class="btn btn-primary">Save changes</button></div></form><form class="danger-zone" method="post" action="<?=e(url('student/actions/transaction-delete.php'))?>" onsubmit="return confirm('Move this transaction to history?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="transaction_id" value="<?=$id?>"><div><strong>Delete transaction</strong><small>Soft delete keeps the history available.</small></div><button class="btn btn-danger">Delete</button></form></section><?php require __DIR__.'/../includes/footer.php';?>